-- Durotar, Valley of Trials and Echo Isles: creature abilities
-- Most of the zone's creatures either had no AI or ran classic rows (Sergeant Curtis even ran Watch Commander Zalaphil's). Durotar is
-- the Cataclysm revamp, so port their abilities from the Cataclysm data, keeping the quest scripts already in place (the Clattering
-- Scorpid totem credit, Raider Jhash's wolf, Naj'tess' red beam). Geolord Mottle's classic Lightning Shield gives way to the Earth
-- Shield he has in the Cataclysm data.

SET @ENTRIES := '3098,3099,3102,3106,3107,3108,3111,3112,3113,3114,3115,3116,3117,3118,3123,3125,3126,3127,3183,3195,3196,3197,3198,3199,3204,3281,3297,5809,5822,5823,5824,5826,5952,5953,10676,37956,37961,38046,38217,39004,39072,39215,39245,39249,39260,39261,39267,39268,39269,39272,39317,39337,39351,39352,39353,39385,39452,39595,39596,39603,42946';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
